              scheme: "bearer";
            }
          }
        },
        {
          name: "jwtAuth";
          value: {
            security_scheme: {
              type: "http";
              scheme: "JWT";
            }
          }
        }
      ]
    }
  }
  servers: {
    url: "http://localhost:8080";
